#!/usr/bin/env python3
"""Experimental *inside-the-module* fuel counter: rewrite WAT generated by WABT.

Charges one unit on entry to every defined function and every loop. This is
not WebAssembly-instruction metering: calls, memory copies and straight-line
work are intentionally under-priced. It demonstrates deterministic trap points
for an agreed rewriting algorithm. Do NOT use for production sandboxes.
Requires WABT wasm2wat and wat2wasm (Apache-2.0).
"""
import pathlib
import re
import subprocess
import sys

CHARGE = """    global.get $colophon_spike_fuel
    i64.eqz
    if
      unreachable
    end
    global.get $colophon_spike_fuel
    i64.const 1
    i64.sub
    global.set $colophon_spike_fuel
"""

def instrument(source: str):
    lines = source.splitlines(keepends=True)
    if not lines[0].startswith("(module"):
        raise ValueError("Expected WABT's linear WAT output")
    output = []
    functions = loops = 0
    pending_function_entry = False
    for line in lines:
        if re.match(r"^\s*\(func\s", line):
            # WABT places (local ...) declarations AFTER the header. WAT
            # requires all such declarations before executable instructions.
            if pending_function_entry:
                raise ValueError("unexpected nested function header")
            output.append(line)
            pending_function_entry = True
            functions += 1
            continue
        if pending_function_entry:
            if re.match(r"^\s*\(local(?:\s|\))", line):
                output.append(line)
                continue
            output.append(CHARGE)
            pending_function_entry = False
        output.append(line)
        if re.match(r"^\s*loop(?:\s|$)", line):
            output.append(CHARGE)
            loops += 1
    if pending_function_entry:
        raise ValueError("unterminated function header")
    text = "".join(output)
    final = text.rfind(")")
    if final < 0:
        raise ValueError("No module close")
    extras = """
  (global $colophon_spike_fuel (mut i64) (i64.const 0))
  (func $colophon_spike_fuel_reset (export "fuel_reset") (param i64)
    local.get 0
    global.set $colophon_spike_fuel)
  (func $colophon_spike_fuel_left (export "fuel_left") (result i64)
    global.get $colophon_spike_fuel)
"""
    return text[:final] + extras + text[final:], functions, loops

def main():
    if len(sys.argv) != 3:
        raise SystemExit("usage: instrument.py original.wasm instrumented.wasm")
    inp, out = map(pathlib.Path, sys.argv[1:])
    source = subprocess.check_output(["wasm2wat", str(inp)], text=True)
    rendered, funcs, loops = instrument(source)
    wat = out.with_suffix(".wat")
    wat.write_text(rendered)
    subprocess.run(["wat2wasm", str(wat), "-o", str(out)], check=True)
    print(f"instrumented functions={funcs} loops={loops} output={out}")

if __name__ == "__main__":
    main()
